SourceCode.Declaration:
internal final class METRebateMatchingHelper
{
    static Map purchTableMap = new Map(Types::Container, Types::Record);
}

Method.Source:
static internal boolean checkIfPricingAttributesAreMatched(
    Common _journalTransaction,
    TAMRebateQueryBuilder _rebateQueryBuilder,
    TAMRebateDate _rebateDate,
    TAMRebateTable _rebateTable)
{
    PurchTable purchTable;
    str tableName;

    if (rebatePerfFlightEnabled)
    {
        if (_journalTransaction is PurchTable)
        {
            purchTable = _journalTransaction as PurchTable;
        }
        else
        {
            tableName = tableId2Name(_rebateQueryBuilder.transTable());
            PurchId purchId = _journalTransaction.(fieldName2Id(tableName2Id(tableName), 'PurchId'));
            container key = [purchId, _rebateTable.RebateCompanyId];

            if (purchTableMap.exists(key))
            {
                purchTable = purchTableMap.lookup(key);
            }
            else
            {
                purchTable = PurchTable::find(purchId);
                purchTableMap.add(key, purchTable);
            }
        }
    }
    else
    {
        tableName = tableId2Name(_rebateQueryBuilder.transTable());
        purchTable = PurchTable::find(_journalTransaction.(fieldName2Id(tableName2Id(tableName), 'PurchId')));
    }

    if (purchTable.RecId)
    {
        return METRebateMatchingHelper::checkIfPricingAttributesAreMatchedForPurchByHash(purchTable, _journalTransaction, tableName, _rebateTable);
    }
    else
    {
        return false;
    }
}

static internal boolean checkIfPricingAttributesAreMatchedForPurchByHash(
    PurchTable _purchTable,
    Common _journalTransaction,
    str _tableName,
    TAMRebateTable _rebateTable)
{
    if (_rebateTable.PricingRuleHeader == 0 && _rebateTable.PricingRuleLine == 0)
    {
        return true;
    }

    PurchLine purchLine = _journalTransaction is PurchLine ?
                          _journalTransaction as PurchLine :
                          PurchLine::findInventTransId(_journalTransaction.(fieldName2Id(tableName2Id(_tableName), 'InventTransId')));

    boolean matchPriceTree = purchLine.LineAmount != 0
                         && (!_rebateTable.PriceComponentCombination
                         || !GUPParameters::find().EnablePriceTree
                         || GUPPricingTree::getComponentCodeNamesLinkedWithPriceTreeFromSalesId(_purchTable.PurchId).in(_rebateTable.getPriceComponentCodeName()));

    if (!matchPriceTree)
    {
        return false;
    }

    boolean headerMatched;
    container headerRuleMatchedkey = [tableNum(PurchTable), _purchTable.RecId, _rebateTable.PricingRuleHeader];

    if (gupRebatePerfFlightEnabled)
    {
        // only match the salestable and salesline attribute
        headerMatched = ruleMatchedCache.exists(headerRuleMatchedkey) ?
                        ruleMatchedCache.lookup(headerRuleMatchedkey) :
                        GUPHashHelper::checkRuleMatchedWithTableOrLineAttribute(_rebateTable.PricingRuleHeader, _purchTable)
                        && !GUPHashHelper::checkRuleMatchedWithExclusion(_rebateTable.PricingRuleHeader, _purchTable);

        if (!ruleMatchedCache.exists(headerRuleMatchedkey))
        {
            ruleMatchedCache.add(headerRuleMatchedkey, headerMatched);
        }

        return headerMatched
            && GUPHashHelper::checkRuleMatchedWithTableOrLineAttribute(_rebateTable.PricingRuleLine, purchLine)
            && !GUPHashHelper::checkRuleMatchedWithExclusion(_rebateTable.PricingRuleLine, purchLine);
    }

    if (ruleMatchedCache.exists(headerRuleMatchedkey))
    {
        headerMatched = ruleMatchedCache.lookup(headerRuleMatchedkey);
    }
    else
    {
        container key = [_purchTable.SalesId, _purchTable.DataAreaId];
        Set headerHashSet = salesTableHashCache.exists(key) ?
                            salesTableHashCache.lookup(key) :
                            GUPHashHelper::calculateHashValueForHashKeySet(GUPHashHelper::getPropertyHashKeySetForPricingObject(_salesTable, GUPPricingAttributeSourceLevel::Header));

        if (!salesTableHashCache.exists(key))
        {
            salesTableHashCache.add(key, headerHashSet);
        }

        headerMatched = GUPHashHelper::checkRuleMatchedWithHashSet(headerHashSet, _rebateTable.PricingRuleHeader, _purchTable);
        ruleMatchedCache.add(headerRuleMatchedkey, headerMatched);
    }

    if (!headerMatched)
    {
        return false;
    }

    container productAttributekey = [purchLine.ItemId, purchLine.DataAreaId];
    Map productAttributeValues = productAttributeCache.exists(productAttributekey) ? productAttributeCache.lookup(productAttributekey) : new Map(Types::String, Types::AnyType);
    Set lineHashSet = GUPHashHelper::calculateHashValueForHashKeySet(GUPHashHelper::getPropertyHashKeySetForPricingObject(purchLine, GUPPricingAttributeSourceLevel::Line, productAttributeValues));

    if (productAttributeCache.exists(productAttributekey))
    {
        productAttributeCache.remove(productAttributekey);
    }
    productAttributeCache.add(productAttributekey, productAttributeValues);

    return headerMatched && GUPHashHelper::checkRuleMatchedWithHashSet(lineHashSet, _rebateTable.PricingRuleLine, purchLine);
}

static internal boolean checkIfRecordLinkedWithPriceTree(
    Common _journalTransaction,
    TAMRebateQueryBuilder _rebateQueryBuilder,
    TAMRebateTable _rebateTable)
{
    if (GUPParameters::find().EnablePriceTree)
    {
        str tableName = tableId2Name(_rebateQueryBuilder.transTable());
        PurchTable purchTable = PurchTable::find(_journalTransaction.(fieldName2Id(tableName2Id(tableName), 'PurchId')));

        if (purchTable.RecId)
        {
            GUPPricingAttributeGroupCombinationName name = _rebateTable.getPriceComponentCodeName();
            SetEnumerator enumerator = METGUPPricingTree_extension::METGetComponentCodeNamesLinkedWithPriceTreeFromPurchId(purchTable.PurchId).getEnumerator();

            while (enumerator.moveNext())
            {
                if (strCmp(name, enumerator.current()) == 0)
                {
                    return true;
                }
            }
        }
        return false;
    }
    else
    {
        return true;
    }
}
